import XCTest
@testable import NotTennaPod

@MainActor final class SynchronizationStatusDateTests: XCTestCase {
    // Values come from the unchanged Android16 DateUtils delegate algorithm
    // running with Android ICU, never from this Swift formatter's output.
    func testSourceRecentFutureMidnightAndWeekBoundaryOracle() {
        for row in Self.oracle {
            XCTAssertEqual(SynchronizationStatusDateFormatter.string(
                from: Date(timeIntervalSince1970: Double(row.time) / 1000),
                relativeTo: Date(timeIntervalSince1970: Double(row.now) / 1000),
                locale: Locale(identifier: row.locale), timeZone: TimeZone(identifier: row.zone)!),
                row.expected, "\(row.locale) \(row.name)")
        }
    }

